const { chromium } = require('playwright');
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:430,height:932},deviceScaleFactor:2});
await p.goto('http://localhost:8888/templates/leasing/?demo');await p.waitForTimeout(4000);
const ferme=p.locator('dialog.modale button:has-text("C\'est parti")'); if(await ferme.count()) await ferme.first().click();
await p.waitForTimeout(400);
console.log('dialogs ouverts',await p.evaluate(()=>document.querySelectorAll('dialog[open]').length));await p.evaluate(()=>document.querySelectorAll('dialog[open]').forEach(d=>d.close()));await p.waitForTimeout(300);
await p.addStyleTag({content:'.bandeau-demo,nav.onglets,dialog.modale,dialog::backdrop{display:none!important}'});
await p.setViewportSize({width:430,height:1600});
const clip=async(fn)=>{let r=await p.evaluate(fn);await p.evaluate(y=>window.scrollTo(0,y-140),r[0]);await p.waitForTimeout(300);r=await p.evaluate(fn);const sy=await p.evaluate(()=>scrollY);return {x:0,y:r[0]-sy,width:430,height:r[1]-r[0]};};
await p.evaluate(()=>document.querySelector('nav.onglets [data-vue="comparaison"]').click()); await p.waitForTimeout(600);
await p.screenshot({path:'leasing-comparaison.png',clip:await clip(()=>{const a=[...document.querySelectorAll('.verdict')].find(v=>/Le moins cher sur/i.test(v.textContent)&&v.getBoundingClientRect().height>0).getBoundingClientRect();const t=[...document.querySelectorAll('.tuile-sc')].pop().getBoundingClientRect();return [a.top+scrollY-16,t.bottom+scrollY+16];})});
await p.screenshot({path:'leasing-kilometrage.png',clip:await clip(()=>{const h=[...document.querySelectorAll('h2')].find(e=>/Selon ton/.test(e.textContent)).getBoundingClientRect();const e=document.querySelector('.essai-km').getBoundingClientRect();return [h.top+scrollY-16,e.top+scrollY-4];})});
await p.evaluate(()=>{const i=document.getElementById('essai-km');i.value=15000;i.dispatchEvent(new Event('input',{bubbles:true}));i.dispatchEvent(new Event('change',{bubbles:true}));}); await p.waitForTimeout(500);
await p.screenshot({path:'leasing-essai15000.png',clip:await clip(()=>{const e=document.querySelector('.essai-km').getBoundingClientRect();return [e.top+scrollY-16,e.bottom+scrollY+16];})});
console.log(await p.evaluate(()=>document.querySelector('.essai-km').innerText));
await p.evaluate(()=>document.querySelector('nav.onglets [data-vue="scenarios"]').click()); await p.waitForTimeout(600);
const c=await clip(()=>{const h=[...document.querySelectorAll('b,h3,span,strong')].filter(e=>e.textContent.trim()==='LLD entretien inclus').pop();let z=h;while(z&&!(z.getBoundingClientRect().width>360&&z.getBoundingClientRect().height>300))z=z.parentElement;const a=z.getBoundingClientRect();return [a.top+scrollY-12,a.bottom+scrollY+12];});
await p.screenshot({path:'leasing-lld.png',clip:c});
await b.close();})();
